        "ticker": "FET",
        "company": "포럼 에너지 테크놀로지스(FET)는 드릴링·완결(completion)·생산 장비 및 관련 솔루션을 공급하는 오일필드 장비·서비스 업체로, 매출이 업스트림 E&P사와 시추 계약자들의 자본지출·시추 활동 사이클에 연동된다. 2025년 3분기 영업손실·순손실을 기록했던 실적이 2025년 4분기와 2026년 1분기 연속으로 흑자 전환되며 마진 회복 국면에 진입했다.",
        "lead": "FET는 최근 1개월 4.43%, 3개월 69.03%, 6개월 32.56% 상승하며 52주 고점 대비 93.89%까지 근접했고, RS 백분위가 1개월 11.4%·3개월 0.7%·6개월 20.4%로 스크리닝 상위권에 위치한다(ADR 4.18%, 200일선 이격 46.97%). 2025년 3분기 영업적자·순손실을 기록했던 실적이 2025년 4분기·2026년 1분기 연속 흑자로 전환되며 마진이 개선됐고, 이를 반영한 모멘텀·실행력 관련 외신 보도가 이어지고 있다.",
