        "ticker": "HOOD",
        "company": "로빈훗 마케츠는 수수료 무료를 표방하는 개인투자자 대상 증권거래 플랫폼으로, 주식·옵션·크립토·이벤트 컨트랙트 거래수익(매출 비중 약 58%)과 순이자수익(34%), 골드 구독료·트럼프계좌 등 기타수익(8%)으로 매출을 구성한다. 최근 Robinhood Chain(토큰화 주식) 메인넷, Rothera 예측시장 거래소, WonderFi 인수를 통한 캐나다 진출, Agentic Trading 등으로 단순 브로커리지에서 금융 슈퍼앱으로 사업을 다각화 중이다. 2Q26(6월 결산분기) 매출 13.08억달러(YoY +32.3%), 세전이익률 54.2%로 이벤트 컨트랙트·옵션·주식 거래 호조가 크립토 부진을 상쇄하며 실적 성장 국면에 있다.",
        "lead": "HOOD는 최근 RS 1개월 25.99%, 3개월 23.28%, 6개월 81.49% 상승하며 스크리닝 상위군에 진입했다. 2026-09-18 SEC의 토큰화 주식 관련 규제 완화 뉴스가 top2 RS 진입 시점과 정확히 일치하는 직접적 트리거로 작용했고, 이에 앞서 2Q26 매출 13.08억달러(YoY +32.3%)·세전이익률 54.2%의 실적 서프라이즈와 Robinhood Chain·Rothera 예측시장·WonderFi 인수 등 신사업 다각화가 랠리의 배경이 됐다.",
