            "statement": "정제 조정총마진이 $680.4M로 확대된 반면 총처리량은 오히려 YoY 2.8% 감소한 181.4천b/d를 기록해, 물량이 아닌 마진 확장이 실적을 견인했다. Singapore 3-1-2 크랙스프레드는 분기 평균 $50/bbl, Hawaii 세그먼트 지표마진은 $46/bbl(캡처율 124%, 가격래그 이익 $77M 포함)을 기록했고, Refining 세그먼트 영업이익은 전년동기 $81.3M에서 $629.9M로, 세그먼트 조정 EBITDA는 $108.4M에서 $552M로 급증했다.",
